.ds-tombol { display: inline-flex; align-items: center; justify-content: center; gap: var(--jarak-2); padding: var(--jarak-2) var(--jarak-4); min-height: 40px; border: 2px solid var(--warna-primer); border-radius: var(--radius-md); background: var(--warna-primer); color: var(--warna-teks-terbalik); font: 600 var(--teks-sm) var(--font-dasar); text-decoration: none; cursor: pointer; }
.ds-tombol:hover { background: var(--warna-primer-gelap); border-color: var(--warna-primer-gelap); }
.ds-tombol--sekunder { background: transparent; color: var(--warna-primer); }
.ds-tombol--sekunder:hover { background: var(--warna-primer-lembut); color: var(--warna-primer-gelap); }
.ds-tombol--bahaya { background: var(--warna-bahaya); border-color: var(--warna-bahaya); }
.ds-tombol--bahaya:hover { background: var(--warna-bahaya-gelap); border-color: var(--warna-bahaya-gelap); }
.ds-tombol--kecil { min-height: 32px; padding: var(--jarak-1) var(--jarak-3); font-size: var(--teks-xs); }
.ds-tombol:disabled { opacity: .5; cursor: not-allowed; }
.ds-navbar__menu a.ds-tombol { color: var(--warna-teks-terbalik); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }

