.ds-field { margin-bottom: var(--jarak-4); }
.ds-field__label { display: block; margin-bottom: var(--jarak-1); font-size: var(--teks-sm); font-weight: 600; }
.ds-field__input { width: 100%; min-height: 42px; padding: var(--jarak-2) var(--jarak-3); border: 1px solid var(--warna-batas); border-radius: var(--radius-md); background: var(--warna-permukaan); color: var(--warna-teks); font: inherit; }
.ds-field__input:focus { outline: 3px solid var(--warna-primer-lembut); border-color: var(--warna-primer); }
.ds-field__bantuan { margin: var(--jarak-1) 0 0; font-size: var(--teks-xs); color: var(--warna-teks-redup); }
.ds-field--galat .ds-field__input { border-color: var(--warna-bahaya); }
.ds-field--galat .ds-field__bantuan { color: var(--warna-bahaya); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }

.ds-navbar { display: block; position: sticky; top: 0; z-index: 10; height: var(--tinggi-navbar); background: var(--warna-permukaan); border-bottom: 1px solid var(--warna-batas); }
.ds-navbar__isi { display: flex; align-items: center; justify-content: space-between; gap: var(--jarak-4); height: 100%; }
.ds-navbar__merek { font: 800 var(--teks-lg) var(--font-judul); color: var(--warna-primer); text-decoration: none; }
.ds-navbar__menu { display: flex; gap: var(--jarak-4); list-style: none; margin: 0; padding: 0; }
.ds-navbar__menu a { color: var(--warna-teks); text-decoration: none; font-size: var(--teks-sm); font-weight: 600; padding: var(--jarak-2) 0; border-bottom: 2px solid transparent; }
.ds-navbar__menu a:hover, .ds-navbar__menu a[aria-current="page"] { border-bottom-color: var(--warna-aksen); }
.ds-navbar__menu a.ds-tombol { color: var(--warna-teks-terbalik); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }

.ds-lencana { display: inline-block; padding: 2px var(--jarak-3); border-radius: var(--radius-penuh); font-size: var(--teks-xs); font-weight: 600; white-space: nowrap; background: var(--warna-netral-lembut); color: var(--warna-teks-redup); }
.ds-lencana--waiting, .ds-lencana--cancelled { background: var(--warna-netral-lembut); color: var(--warna-teks-redup); }
.ds-lencana--called { background: var(--warna-aksen-lembut); color: var(--warna-aksen-teks); }
.ds-lencana--in-service { background: var(--warna-primer-lembut); color: var(--warna-primer-gelap); }
.ds-lencana--completed { background: var(--warna-sukses-lembut); color: var(--warna-sukses); }
.ds-lencana--no-show { background: var(--warna-bahaya-lembut); color: var(--warna-bahaya); }
.ds-lencana--cancelled { text-decoration: line-through; }
.ds-lencana--confirmed { background: var(--warna-permukaan); color: var(--warna-primer); border: 1px solid var(--warna-primer); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }

.ds-kartu { background: var(--warna-permukaan); border: 1px solid var(--warna-batas); border-radius: var(--radius-lg); box-shadow: var(--bayangan-sm); overflow: hidden; }
.ds-kartu__badan { padding: var(--jarak-4) var(--jarak-6); }
.ds-kartu__judul { font: 700 var(--teks-lg) var(--font-judul); margin: 0 0 var(--jarak-1); }
.ds-kartu__meta { color: var(--warna-teks-redup); font-size: var(--teks-sm); margin: 0 0 var(--jarak-3); }
.ds-kartu__kaki { display: flex; justify-content: space-between; align-items: center; gap: var(--jarak-3); padding: var(--jarak-3) var(--jarak-6); border-top: 1px solid var(--warna-batas); background: var(--warna-latar); }
.ds-kartu__gambar { height: 120px; background: var(--warna-primer-lembut); display: flex; align-items: center; justify-content: center; color: var(--warna-primer); font: 700 var(--teks-xl) var(--font-judul); }
.ds-kartu-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: var(--jarak-6); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }

.ds-tiket { display: grid; grid-template-columns: 1fr auto; max-width: 440px; background: var(--warna-permukaan); border: 2px solid var(--warna-primer); border-radius: var(--radius-lg); position: relative; }
.ds-tiket__info { padding: var(--jarak-4) var(--jarak-6); }
.ds-tiket__kode { font-size: var(--teks-xs); color: var(--warna-teks-redup); letter-spacing: .04em; }
.ds-tiket__nama { font: 700 var(--teks-md) var(--font-judul); margin: var(--jarak-1) 0; }
.ds-tiket__nomor { display: flex; flex-direction: column; justify-content: center; align-items: center; min-width: 120px; padding: var(--jarak-4); background: var(--warna-aksen); color: var(--warna-teks); border-left: 2px dashed var(--warna-primer); border-radius: 0 calc(var(--radius-lg) - 2px) calc(var(--radius-lg) - 2px) 0; }
.ds-tiket__nomor strong { font: 800 var(--teks-2xl) var(--font-judul); line-height: 1; font-variant-numeric: tabular-nums; }
.ds-tiket__nomor span { font-size: var(--teks-xs); font-weight: 600; }
.ds-tiket::before, .ds-tiket::after { content: ""; position: absolute; right: 108px; width: 20px; height: 20px; background: var(--warna-latar); border: 2px solid var(--warna-primer); border-radius: var(--radius-penuh); }
.ds-tiket::before { top: -11px; clip-path: inset(50% 0 0 0); }
.ds-tiket::after { bottom: -11px; clip-path: inset(0 0 50% 0); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }

.ds-smartwait { display: flex; align-items: center; gap: var(--jarak-4); max-width: 440px; padding: var(--jarak-4) var(--jarak-6); background: var(--warna-primer-lembut); border-radius: var(--radius-lg); }
.ds-smartwait__menit { font: 800 var(--teks-2xl) var(--font-judul); line-height: 1; color: var(--warna-primer-gelap); font-variant-numeric: tabular-nums; }
.ds-smartwait__teks { margin: 0; font-size: var(--teks-sm); }
.ds-smartwait__catatan { margin: var(--jarak-1) 0 0; font-size: var(--teks-xs); color: var(--warna-teks-redup); }
.ds-preview:focus-visible, .ds-preview :focus-visible { outline: 3px solid var(--warna-aksen); outline-offset: 2px; }
